#!/usr/bin/env python3
"""Turns the sleep pictures in assets/sleep into C++ source.

Run after tools/make_nature_pictures.py:
  python3 tools/embed_pictures.py
The host tests check that the generated file matches the pictures.
"""
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
out = root / "components/vellum_core/src/builtin_pictures.cpp"
files = sorted((root / "assets/sleep").glob("*.png"))
parts = [
    "// Generated by tools/embed_pictures.py from assets/sleep. Do not edit.\n"
    '#include "vellum/sleep_pictures.h"\n\n'
    "namespace vellum {\n"
    "namespace {\n\n"
]
total = 0
for i, f in enumerate(files):
    data = f.read_bytes()
    total += len(data)
    rows = [", ".join(str(b) for b in data[k : k + 24]) for k in range(0, len(data), 24)]
    parts.append(f"const uint8_t kPicture{i}[] = {{\n    " + ",\n    ".join(rows) + "};\n\n")
parts.append("}  // namespace\n\n")
parts.append("const BuiltinPicture kBuiltinPictures[] = {\n")
for i, f in enumerate(files):
    parts.append(f'    {{"vellum-{f.name}", kPicture{i}, sizeof(kPicture{i})}},\n')
parts.append("};\n\n")
parts.append("const int kBuiltinPictureCount = sizeof(kBuiltinPictures) / sizeof(kBuiltinPictures[0]);\n\n")
parts.append("}  // namespace vellum\n")
out.write_text("".join(parts), encoding="utf-8")
print(f"wrote {out.relative_to(root)} ({len(files)} pictures, {total} bytes)")
